#!/usr/bin/env bash
# Prints src/out/testdata/sqxfw_oracle.rs: dvipdfm-x numbers.c's sqxfw (the
# function's own text, taken from the file given as $1) on a fixed set of
# arguments.
set -eu
src=$1
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
{
  echo '#include <stdint.h>'
  echo '#include <stdio.h>'
  echo 'typedef int32_t fixword;'
  # the function, from its header line to its closing brace
  awk '/^int32_t sqxfw \(int32_t sq, fixword fw\)/{p=1} p{print} p&&/^}/{exit}' "$src"
  cat <<'EOF'
static uint32_t s = 20261115u;
static uint32_t rnd(void) { s ^= s << 13; s ^= s >> 17; s ^= s << 5; return s; }
int main(void) {
  static const int32_t edge[] = {0, 1, -1, 2, 15, 16, 17, 65535, 65536, 65537,
    655360, 655361, 1048575, 1048576, 1048577, 2097152, 16777215, 16777216,
    268435455, 268435456, 2147483647, -2147483647, -65536, -1048576, 7, 8, 9};
  int n = sizeof edge / sizeof edge[0], i, j;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      printf("    (%d, %d, %d),\n", edge[i], edge[j], sqxfw(edge[i], edge[j]));
  /* sizes up to 2048pt, fix words up to 16 */
  for (i = 0; i < 400; i++) {
    int32_t sq = (int32_t)(rnd() % (2048u << 16));
    int32_t fw = (int32_t)(rnd() % (16u << 20));
    if (i % 5 == 1) sq = -sq;
    if (i % 7 == 2) fw = -fw;
    printf("    (%d, %d, %d),\n", sq, fw, sqxfw(sq, fw));
  }
  /* any 31-bit arguments */
  for (i = 0; i < 200; i++) {
    int32_t sq = (int32_t)(rnd() >> 1);
    int32_t fw = (int32_t)(rnd() >> 1);
    if (i % 3 == 1) sq = -sq;
    if (i % 4 == 2) fw = -fw;
    printf("    (%d, %d, %d),\n", sq, fw, sqxfw(sq, fw));
  }
  return 0;
}
EOF
} > "$work/t.c"
cc -O0 -fwrapv -o "$work/t" "$work/t.c"
echo '// Generated by crates/flashtex-xetex/src/out/testdata/sqxfw-oracle.sh from'
echo '// TeX Live dvipdfm-x numbers.c: (sq, fw, sqxfw(sq, fw)).'
echo 'const SQXFW_ORACLE: &[(i32, i32, i32)] = &['
"$work/t"
echo '];'
